default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\Wcmsvc\Grouppolicy' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('fMinimizeConnections', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]3)) {
    Write-Output 'Mismatch: HKLM:\Software\Policies\Microsoft\Windows\Wcmsvc\Grouppolicy [fMinimizeConnections]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\Wcmsvc\Grouppolicy')) {
    New-Item -Path 'HKLM:\Software\Policies\Microsoft\Windows\Wcmsvc\Grouppolicy' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\Wcmsvc\Grouppolicy' -Name 'fMinimizeConnections' -Value 3 -PropertyType DWord -Force | Out-Null
exit 0
